window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The address", "year": "ALL PEOPLES", "at": 0.0, "end": 26.367, "map": false, "lines": [{"text": "The author addresses this film to all nation states and peoples, as a warning for Earth.", "at": 0.35, "end": 5.386}, {"text": "Twenty-five sections, held to one standard: documented, attributed, or labeled, and never blurred.", "at": 5.836, "end": 12.794}, {"text": "What closes the report is not held to that standard, because it is not that kind of statement.", "at": 13.244, "end": 17.8}, {"text": "It is the author, in his own voice. It is not a finding, and it is not evidence. It is the reason the document was written.", "at": 18.25, "end": 25.668}]}, {"id": "II", "title": "In his own voice", "year": "VERBATIM", "at": 26.367, "end": 57.867, "map": false, "lines": [{"text": "The author, in his own words.", "at": 26.717, "end": 28.943}]}, {"id": "III", "title": "It is finished", "year": "PERFECT PASSIVE", "at": 57.867, "end": 73.862, "map": false, "lines": [{"text": "“It is finished” is John 19:30. The Greek is tetelestai: a perfect passive. An action completed, whose result stands.", "at": 58.217, "end": 68.905}, {"text": "Not “it ended”, but: it has been completed, and remains so.", "at": 69.355, "end": 73.162}]}, {"id": "IV", "title": "Paid in full?", "year": "1934", "at": 73.862, "end": 113.652, "map": false, "lines": [{"text": "The gloss most people have heard is that the word meant “paid in full”, stamped on receipts.", "at": 74.212, "end": 79.148}, {"text": "It traces to some forty Egyptian tariff receipts published in 1896, and entered scholarship through Moulton and Milligan’s Vocabulary of the Greek Testament, from 1914.", "at": 79.598, "end": 90.054}, {"text": "From 1934, papyri publishers established that the abbreviation on those receipts stands for tetelōnētai: “paid as taxes”. A different word.", "at": 90.504, "end": 101.664}, {"text": "A misread abbreviation, canonised in a lexicon, corrected within twenty years, and preached for a century after the correction. The naming error, operating on scripture itself.", "at": 102.114, "end": 112.953}]}, {"id": "V", "title": "The count", "year": "LUKE 12:7", "at": 113.652, "end": 151.581, "map": false, "lines": [{"text": "The author’s figure is that life is a living polygraph: a person is read continuously, and first of all by God.", "at": 114.002, "end": 119.969}, {"text": "The verse he takes it from is Luke 12:7: “But even the very hairs of your head are all numbered.”", "at": 120.419, "end": 125.105}, {"text": "The Greek is ērithmēntai, the same form as tetelestai: they have been numbered, and stand numbered. The counting is not an ongoing surveillance. It is already complete.", "at": 125.555, "end": 138.087}, {"text": "What almost every citation drops is the sentence it is inside: not one sparrow is forgotten before God. And then: “Fear not.”", "at": 138.537, "end": 146.524}, {"text": "You are known, therefore you are safe. Not: you are known, therefore be careful.", "at": 146.974, "end": 150.881}]}, {"id": "VI", "title": "The weapon", "year": "A PROMISE", "at": 151.581, "end": 188.164, "map": false, "lines": [{"text": "The tenet the author asks the report to close on is Isaiah 54:17 - the only one of these that is a promise rather than a fact.", "at": 151.931, "end": 159.594}, {"text": "“No weapon that is formed against thee shall prosper.”", "at": 160.044, "end": 162.81}, {"text": "It does not say that no weapon will be formed. The Hebrew yutsar is passive: weapons will be formed, and the forming is conceded in the sentence itself.", "at": 163.26, "end": 172.879}, {"text": "What is denied is only that they will prosper: lo yitslach. The verse promises an outcome, not an absence.", "at": 173.329, "end": 180.517}, {"text": "And it ends by calling it a heritage, nachalat: something received rather than achieved.", "at": 180.967, "end": 187.465}]}, {"id": "VII", "title": "A determined game", "year": "1913", "at": 188.164, "end": 232.817, "map": false, "lines": [{"text": "Zermelo’s theorem, 1913: in a finite game of perfect information, the outcome under best play is fixed before the first move.", "at": 188.514, "end": 197.563}, {"text": "Chess is determined. Nobody knows its value. The game is still played.", "at": 198.013, "end": 202.249}, {"text": "Done, and still being played, are not in tension. That is the shape of the perfect passive: completed, the result standing, the moves continuing.", "at": 202.699, "end": 211.637}, {"text": "That history is such a game is the author’s proposition - recorded as his, and not adopted.", "at": 212.087, "end": 217.868}, {"text": "Ada Lovelace, 1843: a symbol may carry “a retrospective and a prospective signification.”", "at": 218.318, "end": 223.988}, {"text": "And her Note G binds every engine, including the one that helped draft this report: it “has no pretensions whatever to originate anything.”", "at": 224.438, "end": 232.119}]}, {"id": "VIII", "title": "Sovereignty", "year": "COMITY", "at": 232.817, "end": 284.496, "map": false, "lines": [{"text": "The author’s last line is also a list. Not a tattoo. Not a city-state, or the law of men, or continuity of government.", "at": 233.167, "end": 241.313}, {"text": "Every item on it is something this report examined: the city-states, the corporate charter, and the continuity apparatus.", "at": 241.763, "end": 248.84}, {"text": "Not one of the claimants examined this year could produce an instrument founding its own authority.", "at": 249.29, "end": 254.006}, {"text": "PPD-40 is classified in full. The emergency action documents are reviewed by no legislature. The NYPD’s foreign liaison service rests, in its own spokesman’s word, on invitation.", "at": 254.456, "end": 266.372}, {"text": "Invitation, classification, custom and force. Each is a thing that can be withdrawn.", "at": 266.822, "end": 272.587}, {"text": "FEMA’s own definition of Enduring Constitutional Government has the President acting toward Congress and the courts as a matter of comity. Comity is what you extend to a body you do not command.", "at": 273.037, "end": 283.797}]}, {"id": "IX", "title": "Three completed things", "year": "LO YITSLACH", "at": 284.496, "end": 315.342, "map": false, "lines": [{"text": "Every discipline in this report makes sense on one assumption: that the record already exists, and the only open question is whether it is read honestly.", "at": 287.096, "end": 295.828}, {"text": "Tetelestai: the work is finished.", "at": 296.278, "end": 298.947}, {"text": "Ērithmēntai: the count is finished.", "at": 299.397, "end": 301.947}, {"text": "Lo yitslach: the weapon will not prosper.", "at": 302.397, "end": 305.191}, {"text": "Two of those are grammar, and one is a promise. State what is there, mark the tier, and stop.", "at": 305.641, "end": 311.142}]}];
window.B0B_INTRO_REEL_DUR=315.342;
window.B0B_FILM={"title": "b0b.dev — Endgame", "page": "/endgame", "share": "https://www.b0b.dev/endgame", "shareText": "Endgame — the close of the b0b.dev report, addressed by its author to all nation states and peoples: three completed things, each held at its tier. Every shot cited.", "webm": "/endgame-reel.webm?v=1", "mp4": "/endgame-reel.mp4?v=1", "poster": "/endgame-poster.jpg?v=1", "download": "/b0b-endgame-film.mp4?v=1", "downloadName": "b0b-dev-endgame.mp4", "kicker": ["endgame · a short film in nine parts", "the close of the report · to all nation states and peoples"], "endLine": "The count is finished. The work is finished.", "lastLineOnCard": false, "credit": "Stills: NASA, the Library of Congress, the National Archives, The Met (CC0), Museo Egizio, the Staatliche Museen zu Berlin, ETH-Bibliothek, US Air Force, Wikimedia Commons contributors (public domain, CC0, CC BY - credited on screen). Film: Robert W. Paul (1903), War Department Film Bulletin 35 (1942), public-domain bird footage. ERC-1155 frames: the author’s own films. Narration: Piper “cori” voice, trained on public-domain LibriVox recordings."};
